import React from 'react';
import { StyleSheet, View, Text, TouchableOpacity, Image } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const ShiftCard = ({ shift }) => {
  const renderEmployees = () => {
    const visibleEmployees = shift.employees.slice(0, 3);
    const remainingCount = shift.additionalCount || 0;

    return (
      <View style={styles.employeesContainer}>
        <View style={styles.employeeAvatars}>
          {visibleEmployees.map((employee, index) => (
            <Image
              key={employee.id}
              source={{ uri: employee.avatar }}
              style={[
                styles.employeeAvatar,
                { marginLeft: index > 0 ? -8 : 0 }
              ]}
            />
          ))}
          {remainingCount > 0 && (
            <View style={[styles.additionalCount, { marginLeft: -8 }]}>
              <Text style={styles.additionalCountText}>+{remainingCount}</Text>
            </View>
          )}
        </View>
      </View>
    );
  };

  const renderStatus = () => {
    if (shift.status === 'missing') {
      return (
        <View style={styles.statusContainer}>
          <Ionicons name="add" size={12} color="#F44336" />
          <Text style={styles.missingText}>{shift.missingText}</Text>
        </View>
      );
    }
    
    if (shift.task) {
      return (
        <View style={styles.statusContainer}>
          <Ionicons name="calendar" size={12} color="#666666" />
          <Text style={styles.taskText}>{shift.task}</Text>
        </View>
      );
    }
    
    return null;
  };

  return (
    <TouchableOpacity style={[styles.card, { backgroundColor: shift.backgroundColor }]}>
      <View style={styles.cardContent}>
        {/* Icon and Title */}
        <View style={styles.headerSection}>
          <View style={[styles.iconContainer, { backgroundColor: shift.iconColor }]}>
            <Ionicons 
              name={shift.iconName} 
              size={16} 
              color="#FFFFFF" 
            />
          </View>
          <Text style={styles.shiftTitle}>{shift.title}</Text>
        </View>

        {/* Time */}
        <Text style={styles.timeText}>
          {shift.startTime} - {shift.endTime}
        </Text>

        {/* Employees */}
        {renderEmployees()}

        {/* Status/Task */}
        {renderStatus()}
      </View>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  card: {
    borderRadius: 4, // Google Calendar rounded corners
    marginBottom: 2, // Google Calendar spacing
    padding: 8, // Google Calendar padding
    // Google Calendar style - clean borders
    borderLeftWidth: 3,
    borderLeftColor: '#20B2AA',
    // Đảm bảo card fill toàn bộ container
    flex: 1,
    minHeight: 40, // Google Calendar compact height
    // Google Calendar - no blur effects
    opacity: 1,
    backdropFilter: 'none',
    filter: 'none',
    // Layer trên cùng
    zIndex: 10,
    elevation: 10, // Android
    // Google Calendar no shadow
    shadowColor: 'transparent',
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0,
    shadowRadius: 0,
    // Đảm bảo nền che phủ hoàn toàn
    backgroundColor: 'rgba(255, 255, 255, 1)', // Solid background
  },
  cardContent: {
    flex: 1,
    // Không có hiệu ứng mờ
    opacity: 1,
    // Đảm bảo nền rõ ràng và che phủ các đường kẻ
    backgroundColor: 'transparent',
    // Đảm bảo che phủ hoàn toàn
    width: '100%',
    height: '100%',
    position: 'relative',
    zIndex: 11, // Cao hơn card
  },
  headerSection: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 2,
  },
  iconContainer: {
    width: 16,
    height: 16,
    borderRadius: 8,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 4,
  },
  shiftTitle: {
    fontSize: 12, // Google Calendar font size
    fontWeight: '500', // Google Calendar font weight
    color: '#3C4043', // Google Calendar text color
    flex: 1,
    // Google Calendar clean text
    opacity: 1,
    textShadowColor: 'transparent',
    lineHeight: 16, // Google Calendar line height
  },
  timeText: {
    fontSize: 10, // Google Calendar time font size
    color: '#5F6368', // Google Calendar secondary text
    marginBottom: 4, // Google Calendar spacing
    // Google Calendar clean text
    opacity: 1,
    textShadowColor: 'transparent',
    lineHeight: 14, // Google Calendar line height
  },
  employeesContainer: {
    marginBottom: 4,
  },
  employeeAvatars: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  employeeAvatar: {
    width: 16,
    height: 16,
    borderRadius: 8,
    borderWidth: 1,
    borderColor: '#FFFFFF',
  },
  additionalCount: {
    width: 16,
    height: 16,
    borderRadius: 8,
    backgroundColor: '#CCCCCC',
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 1,
    borderColor: '#FFFFFF',
  },
  additionalCountText: {
    fontSize: 7,
    fontWeight: 'bold',
    color: '#666666',
  },
  statusContainer: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  missingText: {
    fontSize: 8,
    color: '#F44336',
    fontWeight: '500',
    marginLeft: 2,
  },
  taskText: {
    fontSize: 8,
    color: '#666666',
    marginLeft: 2,
  },
});

export default ShiftCard;
